import{j as e}from"./motion-C33zLNOn.js";import{L as o}from"./LegalLayout-mipSaysw.js";import{u as a}from"./index-BSVw8kHG.js";import"./react-vendor-BlkHZrIR.js";import"./PageHero-CO5ulD7X.js";import"./three-DvkfnHy2.js";function d(){return a("Privacy Policy — Xelvic","How Xelvic collects, uses and protects your information."),e.jsx(o,{eyebrow:"Your privacy",title:"Privacy Policy",updated:"September 2026",intro:"This policy explains what we collect, why, and the control you have. In short: your conversations are yours.",sections:[{heading:"Information we collect",body:["When you create an account we collect your phone number and the username you choose. You may add a display name, photo and bio.","To help you find friends, we match your contacts privately. Numbers never leave your device in a readable form — we only check for matches.","As you use Xelvic we process the content you send so it reaches the right people, plus basic technical data like device type and app version to keep things working."]},{heading:"How we use your information",body:["We use your information to deliver messages and calls, show you moments, drops and rooms from the people you follow, and keep your account secure.","We use aggregate, non-identifying data to understand what is working and to improve Xelvic."]},{heading:"Messages, calls and the Vault",body:["Your calls and chats are encrypted. Call media travels directly between devices and is encrypted in transit.","The Vault is a private, encrypted space for the chats you want hidden. You open it by entering your vault code where you would normally type a name.","Disappearing conversations clear themselves after messages are seen."]},{heading:"What we share",body:["We do not sell your personal information.","We share data only with service providers who help us run Xelvic, and only as needed, or when the law requires it."]},{heading:"Your choices and rights",body:["You can edit or delete your profile details at any time, manage which devices are signed in, and delete your account from settings.","Depending on where you live, you may have additional rights to access or export your data. Contact us and we will help."]},{heading:"Children",body:["Xelvic is not for anyone under 13. If we learn an account belongs to a child under 13, we remove it."]},{heading:"Contact us",body:["Questions about privacy? Email privacy@xelvic.app and our team will get back to you."]}]})}export{d as default};
